import 'package:flutter/material.dart'; import '../../../models/family_member.dart';
class TreeEdgePainter extends CustomPainter{ TreeEdgePainter(this.members,this.positions); final List<FamilyMember> members; final Map<String,Offset> positions; @override void paint(Canvas c, Size s){ final p=Paint()..color=Colors.blueGrey.withOpacity(.45)..strokeWidth=2; for(final m in members){ final a=positions[m.id]; if(a==null)continue; for(final child in m.relations.childrenIds){ final b=positions[child]; if(b!=null)c.drawLine(a+const Offset(44,88), b+const Offset(44,0), p); } for(final sp in m.relations.spouseIds){ final b=positions[sp]; if(b!=null)c.drawLine(a+const Offset(88,44), b+const Offset(0,44), p); } }} @override bool shouldRepaint(c)=>true;}
